 const periods=useMemo(()=>{const keys=monthly.map(x=>x.key),cur=keys.slice(-3),prev=keys.slice(-6,-3),sumRows=(a,k)=>a.reduce((v,x)=>v+Number(x[k]||0),0),c=monthly.filter(x=>cur.includes(x.key)),p=monthly.filter(x=>prev.includes(x.key));return{cur,prev,current:c,previous:p,ready:cur.length===3&&prev.length===3,currentRevenue:sumRows(c,'revenue'),previousRevenue:sumRows(p,'revenue'),currentQty:sumRows(c,'shippedQty')||sumRows(c,'qty'),previousQty:sumRows(p,'shippedQty')||sumRows(p,'qty')}},[monthly]);
 const bridge=useMemo(()=>{const q0=periods.previousQty,q1=periods.currentQty,r0=periods.previousRevenue,r1=periods.currentRevenue,p0=q0?r0/q0:0,p1=q1?r1/q1:0;return{change:r1-r0,growth:r0?(r1-r0)/Math.abs(r0)*100:null,volume:(q1-q0)*(p0+p1)/2,price:(p1-p0)*(q0+q1)/2,qtyGrowth:q0?(q1-q0)/q0*100:null,unitGrowth:p0?(p1-p0)/Math.abs(p0)*100:null}},[periods]);
 const grouped=useMemo(()=>{const make=field=>{const m=new Map();orders.forEach(r=>{const name=String(r[field]||'Unclassified'),v=m.get(name)||{name,revenue:0,profit:0,qty:0,shipped:0,orders:new Set()};v.revenue+=Number(r.revenue_inr||0);v.profit+=Number(r.profit_inr||0);v.qty+=Number(r.order_qty||0);v.shipped+=Number(r.shipped_qty||0);if(r.order_id)v.orders.add(r.order_id);m.set(name,v)});return[...m.values()].map(v=>({...v,count:v.orders.size,margin:v.revenue?v.profit/v.revenue*100:0,share:revenue?v.revenue/revenue*100:0})).sort((a,b)=>b.revenue-a.revenue)};return{country:make('country'),buyer:make('buyer_name'),category:make('product_category'),style:make('style_id')}},[orders,revenue]);
 const contributors=useMemo(()=>{const all=[...periods.prev,...periods.cur],make=field=>{const m=new Map();orders.forEach(r=>{const k=monthKey(r.order_date);if(!all.includes(k))return;const name=String(r[field]||'Unclassified'),v=m.get(name)||{name,previous:0,current:0};if(periods.prev.includes(k))v.previous+=Number(r.revenue_inr||0);else v.current+=Number(r.revenue_inr||0);m.set(name,v)});return[...m.values()].map(v=>({...v,change:v.current-v.previous,growth:v.previous?(v.current-v.previous)/Math.abs(v.previous)*100:null})).sort((a,b)=>Math.abs(b.change)-Math.abs(a.change))};return{category:make('product_category'),buyer:make('buyer_name'),country:make('country')}},[orders,periods]);
 const yoy=useMemo(()=>{const map=new Map(monthly.map(x=>[x.key,x]));return monthly.slice(-6).map(x=>{const key=String(Number(x.key.slice(0,4))-1)+x.key.slice(4),old=map.get(key);return{month:x.month,actual:x.revenue,previous:old?.revenue??null,change:old?x.revenue-old.revenue:null,growth:old&&old.revenue?(x.revenue-old.revenue)/Math.abs(old.revenue)*100:null}})},[monthly]);
 const forecastModel=useMemo(()=>{const values=monthly.map(x=>x.revenue),n=values.length;const predict=(name,train,lead=1)=>{const len=train.length;if(!len)return null;if(name==='3-month moving average')return train.slice(-3).reduce((a,b)=>a+b,0)/Math.min(3,len);if(name==='Seasonal naive (12M)')return len>=12?train[(len-12+((lead-1)%12))%len]:null;const sx=(len-1)*len/2,sxx=(len-1)*len*(2*len-1)/6,sy=train.reduce((a,b)=>a+b,0),sxy=train.reduce((a,b,i)=>a+i*b,0),den=len*sxx-sx*sx;if(!den)return train[len-1];const slope=(len*sxy-sx*sy)/den,intercept=(sy-slope*sx)/len;return Math.max(0,intercept+slope*(len-1+lead))};const names=['3-month moving average','Linear trend','Seasonal naive (12M)'],tested=names.map(name=>{const errors=[],start=Math.max(6,n-6);for(let i=start;i<n;i++){const estimate=predict(name,values.slice(0,i),1);if(estimate==null)continue;errors.push({actual:values[i],error:Math.abs(values[i]-estimate)})}const error=errors.reduce((a,x)=>a+x.error,0),base=errors.reduce((a,x)=>a+Math.abs(x.actual),0);return{name,points:errors.length,mae:errors.length?error/errors.length:null,wape:base?error/base*100:null}}).filter(x=>x.points>=2&&x.wape!=null),best=tested.slice().sort((a,b)=>a.wape-b.wape)[0]||{name:'3-month moving average',wape:null,points:0,mae:null},steps=Number(horizon),range=best.wape==null ? .2 : best.wape/100,rows=Array.from({length:steps},(_,i)=>{const date=monthly.length?new Date(monthly.at(-1).key+'-01T00:00:00Z'):null;if(!date)return null;date.setUTCMonth(date.getUTCMonth()+i+1);const key=date.toISOString().slice(0,7),value=Math.max(0,predict(best.name,values,i+1)??values.slice(-3).reduce((a,b)=>a+b,0)/Math.max(1,Math.min(3,n)));return{key,month:monthLabel(key),forecast:value,lower:Math.max(0,value*(1-range)),upper:value*(1+range)}}).filter(Boolean);return{tested,best,rows,available:n>=8,history:n}},[monthly,horizon]);
 const forecastChart=useMemo(()=>{const past=monthly.slice(-18).map(x=>({month:x.month,actual:x.revenue/1e7,forecast:null,lower:null,upper:null}));const next=forecastModel.rows.map(x=>({month:x.month,actual:null,forecast:x.forecast/1e7,lower:x.lower/1e7,upper:x.upper/1e7}));if(past.length&&next.length)next.unshift({...past.at(-1),forecast:past.at(-1).actual,lower:past.at(-1).actual,upper:past.at(-1).actual});return[...past,...next]},[monthly,forecastModel]);
 const anomalies=useMemo(()=>{const out=[];for(let i=6;i<monthly.length;i++){const vals=monthly.slice(i-6,i).map(x=>x.revenue),sorted=[...vals].sort((a,b)=>a-b),med=(sorted[2]+sorted[3])/2,dev=vals.map(x=>Math.abs(x-med)).sort((a,b)=>a-b),mad=(dev[2]+dev[3])/2,mean=vals.reduce((a,b)=>a+b,0)/6,sd=Math.sqrt(vals.reduce((a,b)=>a+(b-mean)**2,0)/6),score=mad>0?0.6745*(monthly[i].revenue-med)/mad:sd>0?(monthly[i].revenue-mean)/sd:0;if(Math.abs(score)>=2.5)out.push({month:monthly[i].month,direction:monthly[i].revenue>=med?'Unusual spike':'Unusual drop',revenue:monthly[i].revenue,baseline:med,score,deviation:med?(monthly[i].revenue-med)/Math.abs(med)*100:0})}return out.reverse()},[monthly]);
 const concentration=useMemo(()=>{const summarize=arr=>{const total=arr.reduce((a,x)=>a+x.revenue,0),top5=arr.slice(0,5).reduce((a,x)=>a+x.revenue,0);return{top:arr[0],top1:total?((arr[0]?.revenue||0)/total*100):0,top5:total?top5/total*100:0,hhi:total?arr.reduce((a,x)=>a+(x.revenue/total*100)**2,0):0}};return{buyer:summarize(grouped.buyer),country:summarize(grouped.country),category:summarize(grouped.category)}},[grouped]);
 const latest=monthly.at(-1),prior=monthly.at(-2),mom=prior&&prior.revenue?(latest.revenue-prior.revenue)/Math.abs(prior.revenue)*100:null,targetValue=Number(target),targetReady=target!==''&&Number.isFinite(targetValue)&&targetValue>0,achievement=targetReady&&latest?latest.revenue/1e7/targetValue*100:null,topBuyer=grouped.buyer[0],topBuyerRows=topBuyer?orders.filter(r=>(r.buyer_name||'Unclassified')===topBuyer.name):[],topBuyerCost=topBuyerRows.reduce((a,r)=>a+Number(r.total_cost_inr||0),0);
