 const selectedDrillRows=Array.isArray(grouped?.[dimension])?grouped[dimension]:[];const drillRows=selectedDrillRows.map(x=>({...x,rev:inr(x.revenue),prof:inr(x.profit),marginLabel:pct(x.margin),aov:inr(x.count?x.revenue/x.count:0),unit:inr(x.shipped?x.revenue/x.shipped:0)}));
 const actions=[];if(anomalies.length){const x=anomalies[0];actions.push({priority:'High',title:x.direction+' in '+x.month,metric:inr(x.revenue),detail:'Compare buyer, country and category orders with the prior six-month baseline. Confirm whether this is timing, mix or a one-off shipment.'})}if(mom!=null&&mom<=-10)actions.push({priority:'High',title:'Investigate the latest revenue decline',metric:pct(mom)+' MoM',detail:'Review the buyers, countries and categories contributing most to the month-on-month reduction.'});if(concentration.buyer.top1>=20)actions.push({priority:'High',title:'Reduce largest-buyer dependency',metric:pct(concentration.buyer.top1)+' of revenue',detail:'Build a measured pipeline across other active accounts; do not abruptly reduce the leading buyer relationship.'});if(concentration.country.top1>=45)actions.push({priority:'Medium',title:'Review country concentration',metric:pct(concentration.country.top1)+' of revenue',detail:'Protect execution in the largest market and identify adjacent markets with existing product fit.'});if(targetReady&&achievement!=null&&achievement<90)actions.push({priority:'Medium',title:'Latest month below entered target',metric:pct(achievement)+' achieved',detail:'Investigate the shortfall by buyer, country and category before changing the sales plan.'});if(!actions.length)actions.push({priority:'Info',title:'No major revenue risk flags in selected data',metric:'Monitor',detail:'Continue monitoring monthly movement, concentration and forecast backtest accuracy.'});
