  <Panel title="Historical revenue and profit" eyebrow="MONTHLY ACTUALS · ₹ CRORE"><div className="adv-chart tall"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={monthly.map(x=>({...x,revenueCr:x.revenue/1e7,profitCr:x.profit/1e7}))} margin={{top:10,right:18,bottom:4,left:8}}><CartesianGrid strokeDasharray="3 4" vertical={false}/><XAxis dataKey="month" interval="preserveStartEnd" tick={{fontSize:10}}/><YAxis tickFormatter={v=>Number(v).toFixed(0)+' Cr'} width={58}/><Tooltip formatter={v=>inr(Number(v)*1e7)}/><Bar dataKey="revenueCr" name="Revenue" fill="#ed7b39" radius={[4,4,0,0]}/><Line dataKey="profitCr" name="Recorded profit" stroke="#315a84" strokeWidth={2.5} dot={false}/></ComposedChart></ResponsiveContainer></div></Panel>
