 'Supplier Intelligence':{icon:Handshake,kicker:'06 · PROCUREMENT RISK',title:'Supplier Risk & Procurement Intelligence',desc:'Supplier-linked order exposure and supplier master indicators.',metrics:[['Linked Supplier Count',d.suppliers.length.toLocaleString('en-IN'),'Distinct supplier IDs on selected orders'],['Supplier-Linked Revenue',inr(d.suppliers.reduce((s,x)=>s+x.revenue,0)),'Revenue from orders linked to a supplier'],['High-Risk Supplier Count',d.suppliers.filter(s=>s.risk==='High risk').length.toLocaleString('en-IN'),'Score below 60; scored suppliers only'],['Top Supplier Revenue Share',d.revenue?pct((d.suppliers.slice().sort((a,b)=>b.revenue-a.revenue)[0]?.revenue||0)/d.revenue*100):'—','Top supplier-linked revenue ÷ total revenue'],['Supplier-Linked Profit',inr(supplierProfit),'Recorded profit from supplier-linked orders'],['Average Supplier Delay',supplierAvgDelay==null?'—':supplierAvgDelay.toFixed(1)+' days','Average of available supplier master delay values'],['Average Supplier Quality',supplierAvgQuality==null?'—':supplierAvgQuality.toFixed(1)+' / 5','Average of available supplier master quality ratings'],['Average Supplier Score',supplierAvgScore==null?'—':supplierAvgScore.toFixed(1)+' / 100','Average across suppliers with both score inputs']]},
